def _refused(src: str, reason: str) -> None:
    if shutil.which("g++") is None:
        return
    with tempfile.TemporaryDirectory() as tmp:
        prog = Path(tmp, "prog.py")
        prog.write_text(src, encoding="utf-8")
        got = subprocess.run([str(build(prog, "prog.py"))], capture_output=True, text=True, check=False, cwd=tmp)
    assert got.returncode == 70 and reason in got.stderr, got


REFUSED = {
    "memoryview": ("memoryview(b'')\n", "[P2+]"),
    "a_buffer": ("class B:\n    def __buffer__(self, flags):\n        return None\nbytes(B())\n", "[P2+]"),
    "a_buffer_as_an_argument": ("class B:\n    def __buffer__(self, flags):\n        return None\nb'a'.find(B())\n", "[P2+]"),
    "charmap": ("import codecs\ncodecs.charmap_decode(b'a')\n", "_codecs.charmap_decode (not a phase-1 codec"),
    "utf_7": ("import codecs\ncodecs.utf_7_encode('a')\n", "_codecs.utf_7_encode (not a phase-1 codec"),
    "namereplace": ("'\\xe9'.encode('ascii', 'namereplace')\n", "namereplace"),
    # __reduce__ is written (C-3-64); its __getstate__ imports copyreg, as CPython's _PyType_GetSlotNames does, and a closure
    # does not reach what a prelude function imports (TODO)
    "pickling": ("bytearray(b'').__reduce__()\n", "importing 'copyreg'"),
    "sizeof": ("bytearray().__sizeof__()\n", "__sizeof__"),
}


def pytest_generate_tests(metafunc: Any) -> None:
    if "program" in metafunc.fixturenames:
        metafunc.parametrize("program", PROGRAMS, ids=[name for name, _ in PROGRAMS])
    if "refusal" in metafunc.fixturenames:
        metafunc.parametrize("refusal", REFUSED.values(), ids=list(REFUSED))


def test_as_cpython(program: tuple[str, str]) -> None:
    same(program[1])


def test_a_codec_outside_phase_1_is_a_lookup_error_d_20() -> None:
    """CPython has these; a closed world without the module behaves as not installed."""
    if shutil.which("g++") is None:
        return
    src = "for n in ('cp1252', 'iso-8859-2', 'koi8-r'):\n    try:\n        'a'.encode(n)\n    except LookupError as e:\n        print(e)\n"
    with tempfile.TemporaryDirectory() as tmp:
        prog = Path(tmp, "prog.py")
        prog.write_text(src, encoding="utf-8")
        got = subprocess.run([str(build(prog, "prog.py"))], capture_output=True, text=True, check=False, cwd=tmp)
    assert got.stdout == "unknown encoding: cp1252\nunknown encoding: iso-8859-2\nunknown encoding: koi8-r\n", got


def test_streams_write_surrogates_as_cpython() -> None:
    """UTF-8 mode (D-15, on by default since 3.15): stdout surrogateescape, stderr backslashreplace.
    The bytes themselves, which are not UTF-8, so this compares them undecoded."""
    if shutil.which("g++") is None:
        return
    src = ("import sys\nsys.stdout.write('a\\udc80b\\n')\nsys.stderr.write('c\\udc80d\\n')\ntry:\n    sys.stdout.write('\\ud800\\n')\n"
           "except UnicodeEncodeError as e:\n    print(e.encoding, e.start, e.end, e.reason)\nsys.stderr.write('\\ud800\\xe9\\u20ac\\n')\nprint('\\udcff\\xe9\\u20ac')\n"
           "print('a\\ud800', 'b')\n")
    with tempfile.TemporaryDirectory() as tmp:
        prog = Path(tmp, "prog.py")
        prog.write_text(src, encoding="utf-8")
        ref = subprocess.run([sys.executable, str(prog)], capture_output=True, check=False, cwd=tmp)
        got = subprocess.run([str(build(prog, "prog.py"))], capture_output=True, check=False, cwd=tmp)
    assert got.stdout == ref.stdout
    assert got.stderr.split(b"Traceback")[0] == ref.stderr.split(b"Traceback")[0]
    assert (got.returncode == ref.returncode) and ref.stderr.rstrip().endswith(b"surrogates not allowed")
    assert b"\\ud800" in got.stderr


def test_stops_by_name(refusal: tuple[str, str]) -> None:
    _refused(refusal[0], refusal[1])


if __name__ == "__main__":
    for item in PROGRAMS:
        test_as_cpython(item)
    for stop in REFUSED.values():
        test_stops_by_name(stop)
